#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;
typedef unsigned long long ull;

#define MAXN 200005

static char *ibuf;
static size_t ipos = 0, ilen = 0;

static inline ll readInt(void){
    while (ipos < ilen && (ibuf[ipos] < '0' || ibuf[ipos] > '9')) ipos++;
    ll x = 0;
    while (ipos < ilen && ibuf[ipos] >= '0' && ibuf[ipos] <= '9'){
        x = x * 10 + (ibuf[ipos] - '0');
        ipos++;
    }
    return x;
}

static int N, Q;
