static ll *tUk, *tWk;
static int *tUa, *tUb, *tWa, *tWb;
static int HBITS = 1, HMASK = 1;

static int BUm[MAXN], BUp_[MAXN], BWm[MAXN], BWp_[MAXN];

static inline int hidx(ull x){ return (int)((x * 0x9E3779B97F4A7C15ULL) >> (64 - HBITS)); }

static void hput(ll *keys, int *aa, int *bb, ll key, int s, int e){
    int i = hidx((ull)key);
    while (aa[i] != -1) i = (i + 1) & HMASK;
    keys[i] = key; aa[i] = s; bb[i] = e;
}
static inline int hget(const ll *keys, const int *aa, ll key){
    int i = hidx((ull)key);
    while (aa[i] != -1){
        if (keys[i] == key) return i;
        i = (i + 1) & HMASK;
    }
    return -1;
}

static int cmpVP(const void *a, const void *b){
    const VP *x = (const VP *)a, *y = (const VP *)b;
    if (x->v != y->v) return (x->v < y->v) ? -1 : 1;
    return x->p - y->p;
}

/* conta posicoes p em [X,Y] com valor == chave do bloco blk */
static inline ll countRange(const int *posArr, const int *aa, const int *bb, int blk, int X, int Y){
    if (blk < 0 || X > Y) return 0;
    int s = aa[blk], e = bb[blk];
    if (posArr[s] > Y || posArr[e-1] < X) return 0;
    int lo = s, hi = e;
    while (lo < hi){ int m = (lo + hi) >> 1; if (posArr[m] < X) lo = m + 1; else hi = m; }
    int a0 = lo;
    lo = a0; hi = e;
    while (lo < hi){ int m = (lo + hi) >> 1; if (posArr[m] <= Y) lo = m + 1; else hi = m; }
    return (ll)(lo - a0);
}

static inline int findRoot(int x){
    while (par_[x] != x){ par_[x] = par_[par_[x]]; x = par_[x]; }
    return x;
}

static inline int unionSegs(int a, int b){
    if (sZ_[a] < sZ_[b]){ int t = a; a = b; b = t; }
    par_[b] = a;
    if (sL_[b] < sL_[a]) sL_[a] = sL_[b];
    if (sR_[b] > sR_[a]) sR_[a] = sR_[b];
    sZ_[a] += sZ_[b];
    return a;
}

static inline ll activate(int p){
    if (actv[p]) return 0;
    actv[p] = 1; par_[p] = p; sL_[p] = p; sR_[p] = p; sZ_[p] = 1;
    ll add = 0;
