            add += countRange(wPos, tWa, tWb, BWm[p], xLo, rEnd);
            ll x0 = (ll)p - K;
            if (x0 >= (ll)la && x0 <= (ll)rEnd && Uv[x0] == Uv[p] - K) add--;
        }
    }
    if (rr){
        int rb = sR_[rr], loY = p + 1;
        ll hi = (ll)p + K;
        if (hi > (ll)rb) hi = rb;
        if (loY <= hi){
            int yHi = (int)hi;
            add += countRange(uPos, tUa, tUb, BUp_[p], loY, yHi);
            add += countRange(wPos, tWa, tWb, BWp_[p], loY, yHi);
            ll y0 = (ll)p + K;
            if (y0 <= (ll)rb && Uv[y0] == Uv[p] + K) add--;
        }
    }
