            for (int y = ra0; y <= rbb; y++){
                ll loX = (ll)y - K;
                if (loX < (ll)la) loX = la;
                if (loX > (ll)(p - 1)) continue;
                int xLo = (int)loX;
                add += countRange(uPos, tUa, tUb, BUm[y], xLo, p - 1);
                add += countRange(wPos, tWa, tWb, BWm[y], xLo, p - 1);
                if (loX == (ll)y - K && Uv[xLo] == Uv[y] - K) add--;
            }
        }
    }
    int root = p;
    if (rl) root = unionSegs(root, rl);
    if (rr) root = unionSegs(root, rr);
    (void)root;
    return add;
}

static ll answers[MAXN];

int main(void){
    size_t cap = 1 << 23;
    ibuf = (char *)malloc(cap);
    ilen = 0;
