    tUk = (ll*)malloc(sizeof(ll) * cap2); tUa = (int*)malloc(sizeof(int) * cap2); tUb = (int*)malloc(sizeof(int) * cap2);
    tWk = (ll*)malloc(sizeof(ll) * cap2); tWa = (int*)malloc(sizeof(int) * cap2); tWb = (int*)malloc(sizeof(int) * cap2);
    for (int i = 0; i < cap2; i++){ tUa[i] = -1; tWa[i] = -1; }

    {
        int i = 0;
        while (i < N){
            int j = i; ll v = vu[i].v;
            while (j < N && vu[j].v == v) j++;
            hput(tUk, tUa, tUb, v, i, j);
            i = j;
        }
        i = 0;
